(() => {
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const svg=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true">${{back:'<path d="m15 5-7 7 7 7"/>',copy:'<rect x="8" y="3" width="13" height="14" rx="2"/><path d="M16 17v4H3V7h5"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5M6 7a7 7 0 0 1 12-2l2 7M4 12l2 7a7 7 0 0 0 12-2"/>',wallet:'<rect x="3" y="6" width="18" height="15" rx="3"/><path d="M3 9V5l14-3v4M21 12h-6v5h6"/>',plus:'<rect x="3" y="3" width="18" height="18" rx="3" stroke-dasharray="4 3"/><path d="M12 7v10M7 12h10"/>',bank:'<path d="m2 7 10-5 10 5H2zm0 15h20M5 9v10m5-10v10m4-10v10m5-10v10"/>',card:'<rect x="2" y="5" width="20" height="14" rx="3"/><path d="M2 10h20M6 15h4"/>',all:'<rect x="3" y="3" width="6" height="6" rx="1"/><rect x="14" y="3" width="6" height="6" rx="1"/><rect x="3" y="14" width="6" height="6" rx="1"/><path d="M14 15h7m-7 5h7"/>'}[name]||'<path d="M4 3h16v18H4zM8 8h8m-8 5h8m-8 5h4"/>'}</svg>`;
  const image=(name)=>`<img src="assets/icons/${name}.svg" alt="" aria-hidden="true">`;
  const logo=(type)=>type==='bank'?payoutIcon('digital-card'):type==='usdt'?'<img class="payment-method-image" src="assets/payment-methods/usdt.png" alt="" aria-hidden="true">':`<img class="payment-method-image" src="assets/payment-methods/${type==='expert'?'innate':['innate','paytm','arpay'].includes(type)?type:'upi-scan-frame'}.png?v=attached-20261004" alt="" aria-hidden="true">`;
  const uiSvg=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${{refresh:'<path d="M20 7v5h-5M4 17v-5h5M6.4 6.4A8 8 0 0 1 20 12M4 12a8 8 0 0 0 13.6 5.6"/>',chevron:'<path d="m6 9 6 6 6-6"/>',gift:'<rect x="4" y="10" width="16" height="10" rx="2"/><path d="M3 7h18v3H3zM12 7v13M12 7C4 7 6 1 9 3l3 4zm0 0c8 0 6-6 3-4l-3 4z"/>'}[name]}</svg>`;
  const methods=[['upi','UPI-QR'],['innate','umony pay'],['paytm','PAYTM'],['arpay','ARPay']];
  const withdrawalMethods=[['upi','UPI'],['bank','BANK CARD'],['usdt','USDT']];
  const presets=[100,300,500,1000,2000,3000,5000,10000,20000,30000,40000,50000];
  function requestUUID(){if(typeof crypto.randomUUID==='function')return crypto.randomUUID();const bytes=crypto.getRandomValues(new Uint8Array(16));bytes[6]=(bytes[6]&15)|64;bytes[8]=(bytes[8]&63)|128;const hex=Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');return hex.slice(0,8)+'-'+hex.slice(8,12)+'-'+hex.slice(12,16)+'-'+hex.slice(16,20)+'-'+hex.slice(20);}
  function statusBadge(kind,value){const status=String(value).toLowerCase(),tone=['rejected','reject','cancelled','expired'].includes(status)?'red':kind==='deposit'&&['complete','confirmed','confirm'].includes(status)?'green':kind==='withdraw'&&['paid','completed','confirmed','confirm'].includes(status)?'rainbow':status==='processing'?'gray':'blue';return '<span class="wallet-status wallet-status-'+tone+'">'+esc(value)+'</span>';}
  const key=()=> 'cw_wallet_demo_'+(window.ColorWinAuth.session?.user?.id||'preview');
  const payoutKey=()=> 'cw_payout_methods_'+(window.ColorWinAuth.session?.user?.id||'preview');
  const payoutIcon=name=>`<img class="payout-neon-icon" src="assets/icons/payout/${name}.svg" alt="" aria-hidden="true">`;
  const orderNumber=timestamp=>{const stamp=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(new Date(timestamp));const part=n=>stamp.find(p=>p.type===n).value;const bytes=crypto.getRandomValues(new Uint32Array(2));return 'RC'+['year','month','day','hour','minute','second'].map(part).join('')+String(bytes[0]%1000000000).padStart(9,'0')+'abcdef'[bytes[1]%6];};
  const readSession=()=>{try{const s=JSON.parse(sessionStorage.getItem(key())||'{}');let changed=false;for(const o of s.orders||[]){if(!o.number){o.number=/^RC\d{23}[a-f]$/.test(o.id)?o.id:orderNumber(o.createdAt||Date.now());changed=true;}}if(changed)sessionStorage.setItem(key(),JSON.stringify(s));return {orders:Array.isArray(s.orders)?s.orders:[],methods:Array.isArray(s.methods)?s.methods:[],name:s.name||'',upiRotation:s.upiRotation||null,withdrawals:s.withdrawals||[],balance:Number(s.balance||0),bettingNeed:s.bettingNeed==null?(window.ColorWinOperations?.preview()?0:NaN):Number(s.bettingNeed)};}catch{return {orders:[],methods:[],name:'',upiRotation:null};}};
  const payoutState=()=>{try{return JSON.parse(localStorage.getItem(payoutKey())||'null');}catch{return null;}};
  const read=()=>{const s=readSession(),p=payoutState();if(p&&Array.isArray(p.methods)){s.methods=p.methods;s.name=p.name||'';}return s;};
  const write=s=>sessionStorage.setItem(key(),JSON.stringify(s));
  function takeNextUpi(state){
    const pool=[...new Set(window.ColorWinPaymentConfig.upiIds)],version=pool.join('|');
    let rotation=state.upiRotation;
    if(!rotation||rotation.version!==version||!Array.isArray(rotation.remaining))rotation={version,remaining:[],last:null};
    if(!rotation.remaining.length){
      rotation.remaining=[...pool];
      for(let i=rotation.remaining.length-1;i>0;i--){const j=crypto.getRandomValues(new Uint32Array(1))[0]%(i+1);[rotation.remaining[i],rotation.remaining[j]]=[rotation.remaining[j],rotation.remaining[i]];}
      if(pool.length>1&&rotation.remaining[0]===rotation.last)[rotation.remaining[0],rotation.remaining[1]]=[rotation.remaining[1],rotation.remaining[0]];
    }
    const upi=rotation.remaining.shift();rotation.last=upi;state.upiRotation=rotation;return upi;
  }
  const date=v=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(v));
  const time=v=>new Date(v).toLocaleString('sv-SE',{timeZone:'Asia/Kolkata'});
  const empty=()=>'<div class="agency-empty wallet-empty"><img class="cw-no-data-art" src="assets/no-data.svg" alt="" aria-hidden="true"><p>No data</p></div>';
  const header=(title,back='#/wallet',history)=>`<header class="wallet-header"><a href="${back}" aria-label="Go back">${svg('back')}</a><h1>${title}</h1>${history?`<a class="wallet-history-link" href="${history}">${title==='Deposit'?'Deposit history':'Withdrawal history'}</a>`:'<span class="wallet-header-spacer"></span>'}</header>`;
  const balance=(label='Balance')=>`<section class="wallet-balance"><span>${image('ar-wallet')} ${label}</span><strong>₹0 <button type="button" data-refresh aria-label="Refresh balance">${image('refresh-neon')}</button></strong><small>•••• &nbsp; ••••</small></section>`;
  const historyTitle=type=>type==='deposit'?'Deposit history':'Withdrawal history';
  function walletView(){return header('Wallet','#/account')+`<section class="wallet-overview">${svg('wallet')}<strong>₹0</strong><span>Total balance</span><div><p><b>0</b>Total withdrawal amount</p><p><b>0</b>Total deposit amount</p></div></section><main class="wallet-content"><section class="wallet-distribution"><div class="wallet-rings"><div><div class="wallet-ring"><strong>0%</strong></div><b>₹0</b><span>Main wallet</span></div><div><div class="wallet-ring third"><strong>0%</strong></div><b>₹0</b><span>3rd party wallet</span></div></div><button type="button" class="wallet-primary" id="wallet-transfer">Main wallet transfer</button><div class="wallet-shortcuts">${[['deposit','deposit','Deposit'],['withdraw','withdraw','Withdraw'],['deposit/history','deposit-history','Deposit history'],['withdraw/history','wallet-confirmed','Withdrawal history']].map(([route,icon,label])=>`<a href="#/${route}">${image(icon)}<span>${label}</span></a>`).join('')}</div><p class="wallet-note" id="wallet-transfer-status" role="status"></p></section></main>`;}
  const tips=(items)=>'<ul class="wallet-tips">'+items.map(text=>'<li>'+text+'</li>').join('')+'</ul>';
  const depositTips=['If the transfer time is up, please fill out the deposit form again.','The transfer amount must match the order you created.','If you transfer the wrong amount, it may not be credited correctly.','Do not cancel the deposit order after transferring the money.'];
  const withdrawTips=['Checking betting requirement…','Withdraw time 00:00–23:59.','Withdrawal amount ₹100–₹50,000, in multiples of ₹100.','Check your registered payment information before making a withdrawal.','If your registered payment information is incorrect, please contact customer service.'];
  function depositView(){return header('Deposit','#/account','#/deposit/history')+`<main class="wallet-content">${balance()}<div class="pay-method-grid" id="deposit-methods">${methods.map(([id,label],i)=>`<button type="button" data-pay="${id}" class="${i===0?'active':''}" aria-pressed="${i===0}">${logo(id)}<span>${label}</span>${id==='arpay'?'<small class="deposit-bonus-badge">'+uiSvg('gift')+'<span>+2%</span></small>':''}</button>`).join('')}</div><section class="wallet-panel deposit-amount-panel"><h2>${image('digital-card')}Deposit amount</h2><div class="deposit-presets">${presets.map(n=>`<button type="button" data-amount="${n}"><span>₹</span>${n>=1000?n/1000+'K':n}</button>`).join('')}</div><label class="wallet-amount"><span>₹</span><input id="deposit-amount" type="text" inputmode="decimal" placeholder="₹100 – ₹50,000" aria-label="Deposit amount"><button type="button" id="deposit-clear" aria-label="Clear amount">×</button></label><p class="wallet-error" id="deposit-error" role="alert"></p></section><section class="wallet-panel"><h2>${image('deposit-history')}Recharge instructions</h2>${tips(depositTips)}<p class="wallet-note">Pay the exact order amount to Color Win. Confirmation requires payment verification.</p></section><h2 class="wallet-section-heading">${image('wallet-deposit-history')}Deposit history</h2><div id="recent-deposits"></div><a class="wallet-outline" href="#/deposit/history">All history</a></main><footer class="wallet-deposit-footer"><div><small>Recharge method:</small><strong id="deposit-selected">UPI-QR</strong></div><button type="button" id="create-deposit" disabled>Deposit</button></footer>`;}
  function withdrawView(){return header('Withdraw','#/account','#/withdraw/history')+`<main class="wallet-content withdrawal-content">${balance('Available balance')}<button type="button" class="arpay-banner">${logo('arpay')}<div>ARPay<small>Supports UPI for fast payment</small></div></button><div class="withdraw-tabs">${withdrawalMethods.map(([id,label],i)=>`<button type="button" data-withdraw-method="${id}" class="${i===0?'active':''}" aria-pressed="${i===0}">${logo(id)}<span>${label}</span></button>`).join('')}</div><div id="withdraw-saved"></div><p id="withdraw-beneficiary-note" hidden>Need to add beneficiary information to be able to withdraw money</p><section class="wallet-panel withdrawal-amount-panel"><h2 id="withdraw-amount-title">${image('withdraw')}Withdrawal Amount</h2><div id="withdraw-presets" class="withdraw-presets">${[100,5000,10000,15000,20000,30000,40000,50000].map(n=>`<button type="button" data-withdraw-amount="${n}">${n>=1000?n/1000+'K':n}</button>`).join('')}</div><label class="wallet-amount"><span>₹</span><input id="withdraw-amount" type="text" inputmode="decimal" maxlength="11" placeholder="Please enter the amount" aria-label="Withdrawal amount in INR"></label><label id="withdraw-usdt-field" class="wallet-amount" hidden><span class="withdraw-token">${logo('usdt')}<small id="withdraw-network">TRC20</small></span><input id="withdraw-usdt" type="text" inputmode="decimal" placeholder="Please enter USDT amount" aria-label="Withdrawal amount in USDT"></label><p id="withdraw-rate" class="wallet-note" hidden></p><div class="withdraw-amount-line"><span>Withdrawable balance <b>₹0.00</b></span><button type="button" id="withdraw-all">All</button></div><div id="withdraw-received-row" class="withdraw-amount-line"><span>Withdrawal amount received</span><b id="withdraw-received">₹0.00</b></div><button class="wallet-primary" type="button" id="submit-withdraw" disabled>Withdraw</button><p class="wallet-error" id="withdraw-error" role="alert"></p>${tips(withdrawTips)}</section><h2 class="wallet-section-heading">${image('wallet-confirmed')}Withdrawal history</h2>${empty()}<a class="wallet-outline" href="#/withdraw/history">All history</a></main>`;}
  const field=(name,label,placeholder,type='text',extra='')=>`<label class="payout-field"><span>${payoutIcon(({name:"user",phone:"phone",email:"email",ifsc:"key",account:"digital-card",confirm:"check",alias:"user"})[name]||"digital-card")}${label}</span><input name="${name}" type="${type}" placeholder="${placeholder}" required ${extra}></label>`;
  function payoutView(kind){const s=read();let body='';
    if(kind==='upi')body=`<h2 class="payout-information">${logo('upi')}Information UPI</h2>${field('name','UPI name','Please enter UPI name','text',s.name?'readonly value="'+esc(s.name)+'"':'')}<p class="payout-hint">✓ This is your first payout account. The name will be locked once saved, and future methods must use the same name.</p>${field('phone','Phone number','Please enter the phone number','tel','inputmode="numeric" maxlength="10"')}${field('account','UPI ID','Please enter your UPI ID')}${field('confirm','Confirm UPI ID','Please enter your UPI ID')}<p class="payout-warning">Security notice: Never share OTPs or make payments to unsolicited contacts claiming to be support.</p>`;
    if(kind==='bank')body=`<p class="payout-warning pill">ⓘ To ensure the safety of your funds, please bind your bank account.</p><label class="payout-field"><span>${payoutIcon('bank')}Choose a bank</span><button type="button" id="choose-bank" class="wallet-primary">Please select a bank <b>›</b></button><input name="bank" type="hidden"></label>${field('name',"Full recipient's name","Please enter the recipient's name",'text',s.name?'readonly value="'+esc(s.name)+'"':'')}<p class="payout-hint">✓ The first payout name will be locked. Future methods must use the same name.</p>${field('account','Bank account number','Please enter your bank account number','text','inputmode="numeric"')}${field('phone','Phone number','Please enter your phone number','tel','inputmode="numeric" maxlength="10"')}${field('email','Mail','Please input your email','email')}${field('ifsc','IFSC code','Please enter IFSC code','text','maxlength="11"')}`;
    if(kind==='usdt')body=`<p class="payout-warning pill">ⓘ To ensure the safety of your funds, please link your wallet.</p><label class="payout-field"><span>${payoutIcon('digital-card')}Select main network</span><button type="button" class="payout-select" id="choose-network">TRC20 <b>⌄</b></button><input name="network" type="hidden" value="TRC20"></label>${field('account','₮ USDT address','Please enter the USDT address')}${field('alias','Address alias','Please enter a remark for the withdrawal address')}`;
    return header(kind==='usdt'?'Add USDT address':kind==='bank'?'Add a bank account number':'Payment method','#/withdraw')+`<main class="wallet-content payout-content"><form id="payout-form" novalidate data-kind="${kind}">${body}<button type="submit" class="wallet-primary payout-save" disabled>Save</button></form></main>`;
  }
  function historyView(type){const opts=type==='deposit'?methods:[...withdrawalMethods,['arpay','ARPay']];return header(historyTitle(type),'#/'+type)+`<main class="wallet-content wallet-history"><nav class="wallet-history-methods" aria-label="Payment method">${[['all','All'],...opts].map(([id,label],i)=>`<button type="button" data-history-method="${id}" class="${i===0?'active':''}" aria-pressed="${i===0}">${id==='all'?svg('all'):logo(id)}<span>${label}</span></button>`).join('')}</nav><div class="agency-filter-row"><button type="button" id="history-status">All ${uiSvg('chevron')}</button><button type="button" id="history-date">Choose a date ${uiSvg('chevron')}</button></div><div id="wallet-history-records"></div></main>`;}
  function orderCard(order){const expired=Date.now()>=order.expiresAt&&order.status==='to be paid';return `<article class="wallet-order"><header><b>Deposit</b>${statusBadge('deposit',expired?'Expired':order.status)}</header><dl>${[['Order amount','₹'+order.amount],['Type',methods.find(m=>m[0]===order.method)?.[1]||order.method],['Time',time(order.createdAt)],['Order number',order.number||order.id]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}${k==='Order number'?`<button type="button" data-copy-order="${esc(v)}" aria-label="Copy order number">${svg('copy')}</button>`:''}</dd></div>`).join('')}</dl>${!expired&&order.status==='to be paid'?`<a href="#/deposit/pay/${order.id}">View QR payment ›</a>`:''}</article>`;}
  function withdrawalCard(r){const kind=r.payout_snapshot?.kind,type=withdrawalMethods.find(m=>m[0]===kind)?.[1]||kind||'—';return `<article class="wallet-order withdrawal-history-card"><header><b>Withdraw</b>${statusBadge('withdraw',r.status==='paid'?'Completed':r.status)}</header><dl>${[['Balance','₹'+Number(r.amount).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2})],['Type',type],['Time',time(r.created_at)],['Order number',r.number],['UTR',r.payout_reference||'—']].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}${k==='Order number'?`<button type="button" data-copy-order="${esc(v)}" aria-label="Copy order number">${svg('copy')}</button>`:''}</dd></div>`).join('')}</dl></article>`;}
  function findOrder(id){return read().orders.find(o=>o.id.toLowerCase()===String(id).toLowerCase());}
  function paymentView(id){return window.ColorWinCheckout.view(findOrder(id));}
  function view(route){let content=route==='#/wallet'?walletView():route==='#/deposit'?depositView():route==='#/withdraw'?withdrawView():route==='#/deposit/history'?historyView('deposit'):route==='#/withdraw/history'?historyView('withdraw'):route.startsWith('#/deposit/pay/')?paymentView(route.split('/')[3]):payoutView(route.split('/')[3]);return `<section class="wallet-page" data-wallet-route="${esc(route)}">${content}</section>`;}
  async function copy(value,toast){try{await navigator.clipboard.writeText(String(value));toast('Copied successfully');}catch{toast('Unable to copy. Please try again.',true);}}
  async function bind(route,toast){let page=document.querySelector('.wallet-page');if(window.ColorWinOperations&&!window.ColorWinOperations.preview()){try{await window.ColorWinOperations.loadConfig();await window.ColorWinOperations.loadWallet();if(!page.isConnected)return;page.outerHTML=view(route);page=document.querySelector('.wallet-page');window.ColorWinNavigation?.bind(page);}catch(err){if(page.isConnected)page.innerHTML='<main class="wallet-content"><p>'+esc(err.message)+'</p><a href="#/account">Back to account</a></main>';return;}}window.ColorWinAccount.refreshBalance().catch(()=>{});page.querySelectorAll('[data-refresh]').forEach(b=>b.onclick=async()=>{try{await window.ColorWinAccount.refreshBalance();toast('Balance refreshed');}catch{toast('Balance could not be loaded.',true);}});page.querySelector('#wallet-transfer')?.addEventListener('click',()=>{page.querySelector('#wallet-transfer-status').textContent='Wallet transfer is currently unavailable.';});
    if(route==='#/deposit')bindDeposit(page,toast);
    else if(route==='#/withdraw')bindWithdraw(page,toast);
    else if(route.startsWith('#/withdraw/add/'))bindPayout(page,toast);
    else if(route.endsWith('/history'))bindHistory(page,route.startsWith('#/deposit')?'deposit':'withdraw',toast);
    else if(route.startsWith('#/deposit/pay/'))bindPayment(page,route.split('/')[3],toast);
  }
  function bindDeposit(page,toast){let method='upi';const requestId=requestUUID();const input=page.querySelector('#deposit-amount'),button=page.querySelector('#create-deposit'),error=page.querySelector('#deposit-error');const valid=()=>/^\d+(\.\d{1,2})?$/.test(input.value.trim())&&Number(input.value)>=Number(window.ColorWinPaymentConfig.minDeposit||100)&&Number(input.value)<=Number(window.ColorWinPaymentConfig.maxDeposit||50000);
    const update=()=>{button.disabled=!valid();error.textContent=input.value&&!valid()?'Enter an amount from ₹100 to ₹50,000 (up to 2 decimals).':'';page.querySelectorAll('[data-amount]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.amount)===Number(input.value)));};input.oninput=update;page.querySelector('#deposit-clear').onclick=()=>{input.value='';update();input.focus();};page.querySelectorAll('[data-amount]').forEach(b=>b.onclick=()=>{input.value=b.dataset.amount;update();});page.querySelectorAll('[data-pay]').forEach(b=>b.onclick=()=>{if(b.dataset.pay==='arpay'){window.ColorWinCheckout.maintenance(page);return;}method=b.dataset.pay;page.querySelectorAll('[data-pay]').forEach(el=>{el.classList.toggle('active',el===b);el.setAttribute('aria-pressed',String(el===b));});page.querySelector('#deposit-selected').textContent=methods.find(m=>m[0]===method)[1];});
    const prefillKey='cw_deposit_prefill_'+window.ColorWinAuth.session?.user?.id;try{const prefill=sessionStorage.getItem(prefillKey);sessionStorage.removeItem(prefillKey);if(prefill&&presets.includes(Number(prefill))){input.value=prefill;update();}}catch{}
    button.onclick=async()=>{if(!valid()||button.disabled)return;button.disabled=true;try{if(window.ColorWinOperations.preview())throw Error('Sign in to create a deposit order.');const order=['upi','innate','paytm'].includes(method)&&window.ColorWinYoupi?.enabled()?await window.ColorWinYoupi.start(input.value,requestId,method):await window.ColorWinOperations.wallet('create_deposit',{amount:input.value,method,request_id:requestId});const state=read();state.orders.unshift(order);write(state);location.hash='#/deposit/pay/'+order.id;}catch(err){toast(err.message,true);update();}};const recent=read().orders.slice(0,3);page.querySelector('#recent-deposits').innerHTML=recent.length?recent.map(orderCard).join(''):empty();bindCopies(page,toast);
  }
  function bindCopies(page,toast){page.querySelectorAll('[data-copy-order]').forEach(b=>b.onclick=()=>copy(b.dataset.copyOrder,toast));}
  let stopWithdrawRefresh=()=>{};
  function bindWithdraw(page,toast){stopWithdrawRefresh();const requestId=requestUUID();let submitting=false;
    page.querySelector('.arpay-banner').onclick=()=>window.ColorWinCheckout.maintenance(page);
    let kind=sessionStorage.getItem(payoutKey()+'_tab')||'upi';if(!withdrawalMethods.some(m=>m[0]===kind))kind='upi';
    const input=page.querySelector('#withdraw-amount'),tokenInput=page.querySelector('#withdraw-usdt'),error=page.querySelector('#withdraw-error');
    const rate=()=>{const r=Number(window.ColorWinPaymentConfig.usdtInrRate);return Number.isFinite(r)&&r>0?r:null;};
    const amount=v=>/^\d+(\.\d{1,6})?$/.test(v.trim())&&Number.isFinite(Number(v))?Number(v):null;
    const update=(source='inr')=>{
      const r=rate(),value=amount(source==='usdt'?tokenInput.value:input.value);
      if(kind==='usdt'){const target=source==='usdt'?input:tokenInput;target.value=value===null||!r?'':(source==='usdt'?value*r:value/r).toFixed(source==='usdt'?2:6).replace(/(\.\d*?)0+$/,'$1').replace(/\.$/,'');}
      const available=read().balance||0,need=read().bettingNeed;page.querySelector('.wallet-tips li').innerHTML=Number.isFinite(need)?'Need to bet <strong class="withdraw-betting-need">₹'+esc(need.toLocaleString('en-IN',{maximumFractionDigits:2}))+'</strong> to be able to withdraw.':'Betting requirement could not be loaded.';error.textContent=kind==='usdt'?'USDT withdrawals are not enabled.':value===null&&input.value?'Enter a valid amount.':value!==null&&value>0&&(!Number.isInteger(value)||value%100!==0)?'Enter a withdrawal amount in multiples of ₹100.':need>0?'Complete the remaining betting requirement before withdrawing.':value>available?'Insufficient withdrawable balance. Available: ₹'+available.toFixed(2):'';const chosen=selected();page.querySelector('#submit-withdraw').disabled=submitting||kind==='usdt'||!Number.isFinite(need)||need>0||!Number.isInteger(value)||value%100!==0||!chosen?.id||!value||value<Number(window.ColorWinPaymentConfig.minWithdraw||100)||value>Number(window.ColorWinPaymentConfig.maxWithdraw||50000)||value>available;page.querySelector('.withdraw-amount-line span b').textContent='₹'+available.toFixed(2);
      page.querySelector('#withdraw-received').textContent='₹'+(Number.isFinite(value)&&value>0?value:0).toFixed(2);
      page.querySelectorAll('[data-withdraw-amount]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.withdrawAmount)===Number(input.value)&&!!input.value));
    };
    function startRefresh(){
      if(window.ColorWinOperations?.preview())return;
      const owner=window.ColorWinAuth.session?.user?.id;let busy=false,stopped=false;
      const active=()=>page.isConnected&&location.hash==='#/withdraw'&&window.ColorWinAuth.session?.user?.id===owner;
      const refresh=async()=>{
        if(stopped)return;if(!active()){stop();return;}
        if(busy||submitting||document.hidden)return;busy=true;
        try{await window.ColorWinOperations.loadWallet();if(!stopped&&active())update();}
        catch{ /* Keep the last confirmed state; the server rechecks every withdrawal. */ }
        finally{busy=false;}
      };
      const timer=window.setInterval(refresh,5000);
      const routeChanged=()=>{if(!active())stop();};
      function stop(){stopped=true;window.clearInterval(timer);window.removeEventListener('hashchange',routeChanged);window.removeEventListener('focus',refresh);document.removeEventListener('visibilitychange',refresh);}
      stopWithdrawRefresh=stop;window.addEventListener('hashchange',routeChanged);window.addEventListener('focus',refresh);document.addEventListener('visibilitychange',refresh);
    }
    const selected=()=>{const methods=read().methods.filter(m=>m.kind===kind),account=sessionStorage.getItem(payoutKey()+'_selected_'+kind);return methods.find(m=>m.account===account)||methods[0];};
    const draw=()=>{
      page.querySelectorAll('[data-withdraw-method]').forEach(el=>{const yes=el.dataset.withdrawMethod===kind;el.classList.toggle('active',yes);el.setAttribute('aria-pressed',String(yes));});
      const m=selected(),saved=page.querySelector('#withdraw-saved');
      saved.innerHTML=(m?`<button type="button" class="payout-saved payout-saved-${kind}" id="withdraw-beneficiary" aria-label="Choose saved ${kind==='bank'?'bank account':kind==='usdt'?'USDT address':'UPI ID'}">${kind==='bank'?`<span class="saved-bank-brand">${payoutIcon('bank')}<span>${esc(m.bank||'Bank account')}</span></span><span class="saved-bank-number">${esc(m.account.slice(0,Math.min(6,m.account.length-4))+'****'+m.account.slice(-3))}</span>`:`<span class="saved-recipient"><span class="saved-recipient-heading">${logo(kind)}<strong>${esc(m.name||m.alias)}</strong></span><span class="saved-recipient-account">${esc(m.account)}</span>${kind==='usdt'?`<small>${esc(m.network)}</small>`:''}</span>`}${svg('back')}</button>`:'')+`<a class="payout-add ${m?'payout-add-secondary':''}" href="#/withdraw/add/${kind}"><img class="payout-neon-icon" src="assets/icons/payout/scan-target.png" alt="" aria-hidden="true"><span>Add ${kind==='upi'?'UPI':kind==='bank'?'bank card':'USDT address'}</span></a>`;
      saved.querySelector('#withdraw-beneficiary')?.addEventListener('click',()=>{
        const methods=read().methods.filter(x=>x.kind===kind);const options=methods.map(x=>kind==='bank'?(x.bank+' · ••••'+x.account.slice(-4)):((x.name||x.alias)+' · '+x.account));
        sheet(page,'Choose beneficiary',options,options[methods.indexOf(m)],v=>{const next=methods[options.indexOf(v)];sessionStorage.setItem(payoutKey()+'_selected_'+kind,next.account);draw();});
      });
      const usdt=kind==='usdt';page.querySelector('.wallet-balance').hidden=false;
      page.querySelector('#withdraw-beneficiary-note').hidden=!usdt||!!m;
      page.querySelector('#withdraw-usdt-field').hidden=!usdt;page.querySelector('#withdraw-rate').hidden=!usdt;
      page.querySelector('#withdraw-network').textContent=m?.network||'TRC20';
      page.querySelector('#withdraw-rate').textContent=rate()?`1 USDT = ₹${rate().toFixed(2)} · ${m?.network||'TRC20'}`:'Conversion rate is not configured yet.';
      page.querySelector('#withdraw-amount-title').hidden=kind==='bank';page.querySelector('#withdraw-amount-title').innerHTML=usdt?`${logo('usdt')}Select amount of USDT`:`${image('withdraw')}Withdrawal Amount`;
      page.querySelector('#withdraw-presets').hidden=kind!=='upi';page.querySelector('#withdraw-received-row').hidden=usdt;
      input.placeholder=usdt?'Please enter withdrawal amount':'Please enter the amount';input.value='';tokenInput.value='';update();
    };
    page.querySelectorAll('[data-withdraw-method]').forEach(b=>b.onclick=()=>{kind=b.dataset.withdrawMethod;sessionStorage.setItem(payoutKey()+'_tab',kind);draw();});
    input.oninput=()=>{input.value=input.value.slice(0,11);update('inr');};tokenInput.oninput=()=>update('usdt');
    page.querySelectorAll('[data-withdraw-amount]').forEach(b=>b.onclick=()=>{input.value=b.dataset.withdrawAmount;update();});
    page.querySelector('#withdraw-all').onclick=()=>{input.value=String(Math.floor(Math.min(read().balance||0,Number(window.ColorWinPaymentConfig.maxWithdraw||50000))/100)*100);update();};page.querySelector('#submit-withdraw').onclick=async()=>{const b=page.querySelector('#submit-withdraw');if(b.disabled)return;submitting=true;b.disabled=true;try{await window.ColorWinOperations.wallet('withdraw',{amount:input.value,method_id:selected().id,request_id:requestId});await window.ColorWinOperations.loadWallet();toast('Withdrawal submitted. Amount reserved for review.');location.hash='#/withdraw/history';}catch(err){toast(err.message,true);}finally{submitting=false;if(page.isConnected)update();}};draw();startRefresh();
  }
  function bindPayout(page,toast){
    const form=page.querySelector('#payout-form'),kind=form.dataset.kind,save=form.querySelector('[type=submit]');
    const get=name=>form.elements.namedItem(name)?.value.trim()||'';
    const validation=()=>{
      if(kind==='upi'||kind==='bank'){
        if(get('name').length<2)return 'Enter the recipient’s full name.';
        if(!/^\d{10}$/.test(get('phone')))return 'Enter a 10-digit phone number.';
        if(read().name&&get('name')!==read().name)return 'Use the original payout account name.';
      }
      if(kind==='upi'){
        if(!/^[a-zA-Z0-9._-]+@[a-zA-Z][a-zA-Z0-9.-]+$/.test(get('account')))return 'UPI ID format should be name@bank, for example name@ybl.';
        if(get('account').toLowerCase()!==get('confirm').toLowerCase())return 'UPI IDs must match.';
      }
      if(kind==='bank'){
        if(!get('bank'))return 'Choose a bank.';
        if(!/^\d{9,18}$/.test(get('account')))return 'Enter a 9–18 digit bank account number.';
        if(!form.elements.email.validity.valid)return 'Enter a valid email address.';
        if(!/^[A-Z]{4}0[A-Z0-9]{6}$/.test(get('ifsc')))return 'IFSC format is wrong. Use 4 letters, 0, then 6 letters or digits (e.g. HDFC0001234).';
      }
      if(kind==='usdt'){
        if(get('network')==='TRC20'&&!/^T[1-9A-HJ-NP-Za-km-z]{33}$/.test(get('account')))return 'Enter a valid TRC20 address.';
        if(get('network')==='ERC20'&&!/^0x[a-fA-F0-9]{40}$/.test(get('account')))return 'Enter a valid ERC20 address.';
        if(get('alias').length<2)return 'Enter an address alias.';
      }
      return '';
    };
    const update=()=>{save.disabled=[...form.querySelectorAll('input[required]')].some(el=>!el.value.trim())||(kind==='bank'&&!get('bank'));};
    form.oninput=e=>{
      if(e.target.name==='phone')e.target.value=e.target.value.replace(/\D/g,'').slice(0,10);
      if(e.target.name==='ifsc'){const start=e.target.selectionStart,end=e.target.selectionEnd;e.target.value=e.target.value.toUpperCase();e.target.setSelectionRange(start,end);}
      update();
    };
    form.onchange=update;
    page.querySelector('#choose-bank')?.addEventListener('click',()=>bankPicker(page,get('bank'),v=>{form.elements.bank.value=v;page.querySelector('#choose-bank').innerHTML=esc(v)+' <b>›</b>';update();}));
    page.querySelector('#choose-network')?.addEventListener('click',()=>sheet(page,'Select main network',['TRC20','ERC20'],get('network'),v=>{form.elements.network.value=v;page.querySelector('#choose-network').innerHTML=v+' <b>⌄</b>';update();}));
    form.onsubmit=async e=>{
      e.preventDefault();const issue=validation();if(issue){toast(issue,true);return;}
      const state=read(),account=kind==='upi'?get('account').toLowerCase():get('account');
      if(state.methods.some(m=>m.kind===kind&&(kind==='upi'?m.account.toLowerCase()===account.toLowerCase():m.account===account))){toast('This payment method is already saved.',true);return;}
      const method={kind,account,name:get('name'),phone:get('phone'),bank:get('bank'),email:get('email'),ifsc:get('ifsc'),network:get('network'),alias:get('alias')};
      try{save.disabled=true;const stored=await window.ColorWinOperations.wallet('save_method',{kind,details:method});method.id=stored.id;}catch(err){toast(err.message,true);update();return;}state.methods.push(method);if(kind!=='usdt'&&!state.name)state.name=method.name;
      try{localStorage.setItem(payoutKey(),JSON.stringify({methods:state.methods,name:state.name}));write(state);sessionStorage.setItem(payoutKey()+'_tab',kind);sessionStorage.setItem(payoutKey()+'_selected_'+kind,account);}catch{toast('Unable to save. Allow browser storage and try again.',true);return;}
      toast('Payment method saved');location.hash='#/withdraw';
    };update();
  }
  function bankPicker(page,selected,onConfirm){
    const d=document.createElement('dialog');d.className='agency-picker wallet-picker bank-picker';let value=selected;
    d.innerHTML='<div class="agency-picker-top"><button type="button" data-cancel>Cancel</button><strong>Choose a bank</strong><span aria-hidden="true"></span></div><input type="search" class="bank-search" placeholder="Search bank name" aria-label="Search bank name"><div class="bank-results agency-tier-wheel" role="listbox" aria-label="Banks"></div><p class="bank-empty" hidden>No banks found</p>';
    const list=d.querySelector('.bank-results'),search=d.querySelector('.bank-search');
    const draw=()=>{
      const q=search.value.trim().toLowerCase();const names=(window.ColorWinBanks||[]).filter(name=>name.toLowerCase().includes(q));
      list.innerHTML=names.map(name=>`<button type="button" role="option" aria-selected="${name===value}" data-value="${esc(name)}" class="${name===value?'selected':''}">${esc(name)}</button>`).join('');
      d.querySelector('.bank-empty').hidden=!!names.length;
      list.querySelectorAll('[data-value]').forEach(b=>b.onclick=()=>{onConfirm(b.dataset.value);d.close();});
    };
    search.oninput=draw;d.querySelector('[data-cancel]').onclick=()=>d.close();
    d.onclick=e=>{if(e.target===d)d.close();};d.onclose=()=>d.remove();page.append(d);draw();d.showModal();
  }
  function sheet(page,title,options,selected,onConfirm){const d=document.createElement('dialog');d.className='agency-picker wallet-picker';let value=selected||options[0];d.innerHTML=`<div class="agency-picker-top"><button type="button" data-cancel>Cancel</button><strong>${title}</strong><button type="button" data-confirm>Confirm</button></div><div class="agency-tier-wheel">${options.map(o=>`<button type="button" data-value="${esc(o)}" class="${o===value?'selected':''}">${esc(o)}</button>`).join('')}</div>`;page.append(d);d.querySelectorAll('[data-value]').forEach(b=>b.onclick=()=>{value=b.dataset.value;d.querySelectorAll('[data-value]').forEach(el=>el.classList.toggle('selected',el===b));});d.querySelector('[data-cancel]').onclick=()=>d.close();d.querySelector('[data-confirm]').onclick=()=>{onConfirm(value);d.close();};d.onclick=e=>{if(e.target===d)d.close();};d.onclose=()=>d.remove();d.showModal();}
  function bindHistory(page,type,toast){let method='all',status='All',selectedDate='';const draw=()=>{const list=type==='deposit'?read().orders.filter(o=>(method==='all'||o.method===method)&&(status==='All'||(Date.now()>=o.expiresAt&&o.status==='to be paid'?'Expired':o.status).toLowerCase()===status.toLowerCase())&&(!selectedDate||date(o.createdAt)===selectedDate)):(read().withdrawals||[]).filter(o=>(method==='all'||o.payout_snapshot.kind===method)&&(status==='All'||o.status.toLowerCase()===status.toLowerCase().replace('completed','paid'))&&(!selectedDate||date(o.created_at)===selectedDate));page.querySelector('#wallet-history-records').innerHTML=list.length?list.map(type==='deposit'?orderCard:withdrawalCard).join('')+'<p class="agency-no-more">No more</p>':empty();bindCopies(page,toast);};page.querySelectorAll('[data-history-method]').forEach(b=>b.onclick=()=>{method=b.dataset.historyMethod;page.querySelectorAll('[data-history-method]').forEach(el=>{el.classList.toggle('active',el===b);el.setAttribute('aria-pressed',String(el===b));});draw();});page.querySelector('#history-status').onclick=()=>sheet(page,'Status',type==='deposit'?['All','Pending','Complete','To be paid','Expired','Cancelled']:['All','Completed','Pending','Rejected','Processing'],status,v=>{status=v;page.querySelector('#history-status').innerHTML=esc(v)+' '+uiSvg('chevron');draw();});page.querySelector('#history-date').onclick=()=>walletDatePicker(page,{value:selectedDate||date(Date.now()),onConfirm:v=>{selectedDate=v;page.querySelector('#history-date').innerHTML=esc(v||'Choose a date')+' '+uiSvg('chevron');draw();}});draw();}
  function bindPayment(page,id,toast){window.ColorWinCheckout.bind(page,findOrder(id),{read,write,toast});}
  function walletDatePicker(page,{value,onConfirm}){
    const dialog=document.createElement('dialog');dialog.className='agency-picker wallet-date-picker';dialog.setAttribute('aria-label','Choose a date');
    let [year,month,dayValue]=value.split('-').map(Number);let pending=value;
    dialog.innerHTML='<div class="date-picker-handle"></div><div class="agency-picker-top"><button type="button" data-cancel>Cancel</button><strong>Choose a date</strong><button type="button" data-confirm>Confirm</button></div><div class="date-picker-summary"><span>Selected date</span><strong id="date-picker-preview"></strong></div><div class="date-picker-labels"><span>Year</span><span>Month</span><span>Day</span></div><div class="agency-date-wheels"></div><div class="date-picker-actions"><button type="button" data-date-clear>All dates</button><button type="button" data-date-today>Today</button></div>';
    page.append(dialog);const box=dialog.querySelector('.agency-date-wheels');
    const draw=()=>{const max=new Date(year,month,0).getDate();dayValue=Math.min(dayValue,max);pending=[year,String(month).padStart(2,'0'),String(dayValue).padStart(2,'0')].join('-');dialog.querySelector('#date-picker-preview').textContent=new Intl.DateTimeFormat('en-IN',{day:'numeric',month:'long',year:'numeric'}).format(new Date(year,month-1,dayValue));
      box.innerHTML=[['Year',Array.from({length:Math.max(year,new Date().getFullYear())-2019},(_,i)=>2020+i),year],['Month',Array.from({length:12},(_,i)=>i+1),month],['Day',Array.from({length:max},(_,i)=>i+1),dayValue]].map(([label,values,selected])=>'<div class="agency-wheel" role="listbox" aria-label="'+label+'">'+values.map(n=>'<button type="button" role="option" aria-selected="'+(n===selected)+'" data-part="'+label+'" data-value="'+n+'" class="'+(n===selected?'selected':'')+'">'+(label==='Year'?n:String(n).padStart(2,'0'))+'</button>').join('')+'</div>').join('');
      box.querySelectorAll('[data-part]').forEach(b=>b.onclick=()=>{const n=Number(b.dataset.value);if(b.dataset.part==='Year')year=n;else if(b.dataset.part==='Month')month=n;else dayValue=n;draw();});requestAnimationFrame(()=>box.querySelectorAll('.selected').forEach(b=>b.parentElement.scrollTop=b.offsetTop-(b.parentElement.clientHeight-b.clientHeight)/2));};
    dialog.querySelector('[data-cancel]').onclick=()=>dialog.close();dialog.querySelector('[data-confirm]').onclick=()=>{onConfirm(pending);dialog.close();};dialog.querySelector('[data-date-clear]').onclick=()=>{onConfirm('');dialog.close();};dialog.querySelector('[data-date-today]').onclick=()=>{[year,month,dayValue]=date(Date.now()).split('-').map(Number);draw();};dialog.onclick=e=>{if(e.target===dialog)dialog.close();};dialog.onclose=()=>dialog.remove();dialog.showModal();draw();
  }
  const matches=route=>['#/wallet','#/deposit','#/withdraw','#/deposit/history','#/withdraw/history','#/withdraw/add/upi','#/withdraw/add/bank','#/withdraw/add/usdt'].includes(route)||route.startsWith('#/deposit/pay/');
  window.ColorWinWallet={matches,view,bind,bankPicker,sheet,datePicker:walletDatePicker};
})();


